/* One semantic token authority. Compatibility selectors retain their original conditional order.
   Sections: foundations/aliases, base+layout, components+states, responsive conditions.
   Immutable source snapshot: docs/qa/design-system-implementation-20261026/before. */
:root { color-scheme:dark;
  --text-scale:1;
  --ui-canvas:#101010;
  --ui-panel:#1B1B1B;
  --ui-raised:#242424;
  --ui-inset:#141414;
  --ui-chrome:#151515;
  --ui-hover:#303030;
  --ui-pressed:#3D3D3D;
  --ui-media:#050505;
  --ui-compare:#080808;
  --ui-strong:#F4F4F2;
  --ui-body:#DEDEDB;
  --ui-muted:#BDBDBB;
  --ui-disabled:#A6A6A3;
  --ui-line:#383838;
  --ui-control:#858585;
  --ui-selected:#2A2A28;
  --ui-marker:#D8D8D2;
  --ui-selection-edge:#EEEEEE;
  --ui-focus:#E4DDBE;
  --ui-error:#FFB49D;
  --ui-error-bg:#28201E;
  --ui-warning:#E6C58B;
  --ui-primary:var(--ui-strong);
  --ui-on-primary:var(--ui-canvas);
  --ui-waveform-stroke:#DDDDDD;
  --ui-space-1:.25rem;
  --ui-space-2:.5rem;
  --ui-space-3:.75rem;
  --ui-space-4:1rem;
  --ui-space-6:1.5rem;
  --ui-space-8:2rem;
  --ui-radius-clip:.25rem;
  --ui-radius-control:.375rem;
  --ui-radius-panel:.5rem;
  --ui-radius-dialog:.75rem;
  --ui-control-min:36px;
  --ui-meta:calc(.75rem * var(--text-scale));
  --ui-item:calc(.8125rem * var(--text-scale));
  --ui-body-size:calc(.875rem * var(--text-scale));
  --ui-section:calc(1rem * var(--text-scale));
  --ui-context:calc(1.125rem * var(--text-scale));
  --ui-title:calc(1.25rem * var(--text-scale));
  --ui-display:calc(1.5rem * var(--text-scale));
  --ui-weight-normal:400;
  --ui-weight-label:500;
  --ui-weight-heading:600;
  --ui-leading-body:1.45;
  --ui-leading-control:1.45;
  --ui-leading-heading:1.4;
  --ui-motion:120ms;
  --ui-ease:cubic-bezier(.2,0,0,1);
  --ui-font:system-ui,-apple-system,"Apple SD Gothic Neo","Noto Sans KR",sans-serif;
  --ui-font-timecode:ui-monospace,monospace;
  --ui-shadow:#0006;
  --ui-shadow-notice:#0008;
  --ui-backdrop:#000b;
  --ui-shadow-deep:#0009;
  --ui-disabled-edge:#555555;
  --ui-test-edge:#797977;
  }
* { box-sizing:border-box; }
body { margin:0; background:var(--ui-canvas); color:var(--ui-strong); font:var(--ui-body-size)/1.5 system-ui,sans-serif; }
header { height:64px; border-bottom:1px solid var(--ui-line); display:flex; align-items:center; padding:0 var(--ui-space-6); }
header b { font-size:var(--ui-display); letter-spacing:-1px; }
header span { color:var(--ui-muted); }
button,a,input,select,textarea { font:inherit; }
button,.download { border:1px solid var(--ui-line); background:var(--ui-raised); color:white; border-radius:var(--ui-radius-control); padding:9px var(--ui-space-3); cursor:pointer; min-height:40px; text-decoration:none; }
button:hover { background:var(--ui-hover); }
button.primary { background:var(--ui-strong); color:var(--ui-canvas); border-color:var(--ui-strong); }
button:disabled { opacity:.45; cursor:wait; }
button.active { border-color:var(--ui-control); background:var(--ui-hover); }
input,select,textarea { background:var(--ui-canvas); color:white; border:1px solid var(--ui-control); border-radius:var(--ui-radius-control); width:100%; padding:9px; }
input[type=file] { font-size:var(--ui-meta); }
label { display:block; color:var(--ui-muted); margin:10px 0 5px; }
h1 { font-size:var(--ui-title); margin:0; }
h2 { font-size:var(--ui-body-size); margin:0 0 var(--ui-space-3); }
h3 { font-size:var(--ui-body-size); margin:var(--ui-space-3) 0; }
p { margin:var(--ui-space-2) 0; }
.muted,small { color:var(--ui-muted); }
.project-empty { max-width:38rem; margin:var(--ui-space-4) 0 var(--ui-space-8); padding:var(--ui-space-6); background:var(--ui-panel); border:1px solid var(--ui-line); border-radius:var(--ui-radius-panel); }
.project-empty[hidden] { display:none; }
.audio-section:has(.project-empty:not([hidden])) > :not(.project-empty) { display:none; }
.project-empty p { color:var(--ui-body); margin:var(--ui-space-2) 0 var(--ui-space-4); }
small { font-size:var(--ui-meta); }
.row { display:flex; gap:var(--ui-space-2); align-items:center; }
.row>* { min-width:0; flex:1; }
.toolbar { padding:var(--ui-space-4) var(--ui-space-6); display:flex; align-items:center; border-bottom:1px solid var(--ui-line); }
.toolbar select { width:230px; }
.toolbar .spacer { flex:1; }
#notice { padding:var(--ui-space-2) var(--ui-space-6); background:var(--ui-raised); color:var(--ui-body); font-size:var(--ui-meta); min-height:34px; }
.error { color:var(--ui-error)!important; }
main { display:grid; grid-template-columns:230px minmax(360px,1fr) 310px; min-height:calc(100vh - 160px); }
aside { padding:var(--ui-space-4); border-right:1px solid var(--ui-line); }
article { padding:20px; min-width:0; }
.inspector { border-left:1px solid var(--ui-line); border-right:0; min-width:0; }
section { padding:var(--ui-space-4) 0; border-bottom:1px solid var(--ui-line); }
section:first-child { padding-top:0; }
.shot { display:flex; gap:var(--ui-space-3); width:100%; text-align:left; margin:var(--ui-space-2) 0; }
.thumb { width:68px; height:44px; background:var(--ui-compare); object-fit:cover; }
.empty { padding:40px 20px; text-align:center; color:var(--ui-muted); border:1px dashed var(--ui-control); border-radius:var(--ui-radius-panel); }
.preview { aspect-ratio:16/9; display:flex; align-items:center; justify-content:center; overflow:hidden; border:1px solid var(--ui-line); border-radius:var(--ui-radius-panel); }
.preview img,.preview video { width:100%; height:100%; object-fit:contain; }
.preview.portrait { aspect-ratio:9/16; max-height:560px; margin:auto; }
.take-strip { display:flex; gap:10px; overflow:auto; padding:14px 0; }
.take-strip button { min-width:100px; text-align:left; }
.take-strip img { width:90px; height:54px; object-fit:cover; display:block; margin-bottom:6px; }
.badge { font-size:var(--ui-meta); padding:3px 6px; border:1px solid var(--ui-control); border-radius:var(--ui-radius-clip); color:var(--ui-body); }
.timeline { margin-top:20px; border:1px solid var(--ui-line); border-radius:var(--ui-radius-panel); padding:14px; background:var(--ui-inset); }
.clip-row { display:grid; grid-template-columns:28px 1fr 1fr 70px 70px 66px; gap:6px; align-items:center; margin:6px 0; font-size:var(--ui-meta); }
.clip-row input,.clip-row select { padding:6px; }
.clip-row button { padding:2px; }
.lt-ui .clip-row .clip-field { min-width:0; margin:0; font-size:inherit; }
.clip-field-name { display:none; }
.lt-ui .clip-overlay { margin:0 0 var(--ui-space-3); padding:var(--ui-space-2) 0; border-bottom:1px solid var(--ui-line); }
.lt-ui .clip-overlay>summary { min-height:var(--ui-control-min); padding:var(--ui-space-2) 0; color:var(--ui-body); overflow-wrap:anywhere; }
.lt-ui .clip-overlay>summary span { margin-inline-start:var(--ui-space-2); color:var(--ui-muted); font-size:var(--ui-meta); }
.lt-ui .clip-overlay label { min-width:0; margin:var(--ui-space-2) 0; }
.lt-ui .clip-overlay-fields { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--ui-space-2) var(--ui-space-3); }
.lt-ui .clip-overlay :is(input,select),.lt-ui .timeline-frame-preview :is(input,select) { font-variant-numeric:tabular-nums; }
.lt-ui .clip-overlay p,.lt-ui .timeline-frame-preview p { line-height:1.6; overflow-wrap:anywhere; }
.lt-ui .timeline-frame-preview { margin:var(--ui-space-3) 0; padding:var(--ui-space-3) 0; border-top:1px solid var(--ui-line); border-bottom:1px solid var(--ui-line); }
.lt-ui .timeline-frame-preview .row { flex-wrap:wrap; align-items:end; }
.lt-ui .timeline-frame-preview .row>label { flex:1 1 10rem; }
.lt-ui .timeline-frame-preview button { flex:0 1 auto; }
.lt-ui #timelineFrameImage { display:block; width:100%; max-height:360px; object-fit:contain; background:var(--ui-media); }
.lt-ui #timelineFrameImage[hidden] { display:none; }
.track { display:flex; height:28px; gap:2px; margin:var(--ui-space-3) 0; background:var(--ui-media); }
.track span { display:flex; align-items:center; background:var(--ui-line); border:1px solid var(--ui-control); padding:3px; overflow:hidden; white-space:nowrap; font-size:var(--ui-meta); }
.caption-row { display:grid; grid-template-columns:65px 65px minmax(0,1fr) var(--ui-control-min); gap:5px; margin:6px 0; }
.caption-row button { padding:2px; }
.job { background:var(--ui-raised); border:1px solid var(--ui-line); border-radius:var(--ui-radius-control); padding:var(--ui-space-3); margin:10px 0; overflow-wrap:anywhere; }
.job a { color:white; display:inline-block; margin:var(--ui-space-2); }
.job progress { width:100%; accent-color:var(--ui-muted); }
dialog { background:var(--ui-panel); color:white; border:1px solid var(--ui-control); border-radius:var(--ui-radius-panel); width:min(640px,95vw); max-height:90vh; overflow:auto; padding:var(--ui-space-6); }
dialog::backdrop { background:var(--ui-backdrop); }
details { margin:var(--ui-space-3) 0; }
summary { cursor:pointer; color:var(--ui-muted); }
.library { display:grid; grid-template-columns:repeat(auto-fill,minmax(145px,1fr)); gap:10px; }
.library img { width:100%; height:90px; object-fit:cover; }
audio { width:100%; height:36px; }
#downloadPreview { margin:var(--ui-space-3) 0; }
#downloadPreview video { width:100%; max-height:360px; }
#compareDialog small { overflow-wrap:anywhere; display:block; }
#compareDialog img,#compareDialog video { max-height:50vh; object-fit:contain; background:var(--ui-compare); }
:focus-visible { outline:2px solid var(--ui-focus); outline-offset:3px; }
[hidden] { display:none!important; }
@media(max-width:1050px) {
main { grid-template-columns:190px minmax(300px,1fr); }
.inspector { grid-column:1/-1; border-top:1px solid var(--ui-line); display:grid; grid-template-columns:1fr 1fr; gap:var(--ui-space-6); }
.toolbar { flex-wrap:wrap; }
}
@media(max-width:700px) {
header { padding:var(--ui-space-3); height:auto; }
header { flex-wrap:wrap; }
header span:not(#providerBadge) { display:none; }
header #providerBadge { display:inline-block; }
.toolbar { padding:var(--ui-space-3); }
main { display:block; }
aside { border-bottom:1px solid var(--ui-line); }
#shotlist { display:flex; overflow:auto; }
.shot { min-width:160px; }
.inspector { display:block; }
article { padding:var(--ui-space-3); }
.clip-row { grid-template-columns:20px 1fr 1fr 58px 58px 54px; gap:3px; }
.clip-row input,.clip-row select { font-size:var(--ui-meta); min-width:0; }
.toolbar button { font-size:var(--ui-meta); }
h1 { font-size:var(--ui-section); }
}
::placeholder { color:var(--ui-muted); opacity:1; }
button,input,select,textarea,.download { border-color:var(--ui-control); }
p,li,h1,h2,label { overflow-wrap:anywhere; }
.clip-row button { min-width:26px; min-height:32px; }
button { white-space:normal; word-break:keep-all; }
small,.badge { font-size:var(--ui-meta); }
label { font-size:var(--ui-body-size); }
.toolbar { gap:10px; flex-wrap:wrap; }
.toolbar>button { flex-shrink:0; }
.toolbar select { max-width:100%; }
.toolbar .spacer { display:none; }
.management { position:relative; margin:0; }
.management[open] { width:100%; padding:var(--ui-space-3); border:1px solid var(--ui-line); }
.management button { margin:var(--ui-space-1); }
.flow-nav { display:flex; flex-wrap:wrap; gap:var(--ui-space-2); padding:var(--ui-space-4) var(--ui-space-6); background:var(--ui-panel); }
.flow-nav button[aria-current=step] { background:var(--ui-strong); color:var(--ui-canvas); }
.flow-summary { padding:0 var(--ui-space-6) var(--ui-space-3); background:var(--ui-panel); }
#guidedBrief { max-width:760px; }
.guide-next { margin:var(--ui-space-4) 0; }
.guided-card { border:1px solid var(--ui-line); padding:var(--ui-space-4); border-radius:var(--ui-radius-panel); margin:var(--ui-space-4) 0; }
body[data-guided=true]:not([data-step="4"]) #review,body[data-guided=true]:not([data-step="4"]) #render { display:none; }
body[data-guided=true] main { display:block; max-width:1100px; margin:auto; }
body[data-guided=true] #chatWorkspace { display:none; }
body[data-guided=true][data-step="1"] #chatPanel,body[data-guided=true][data-step="3"] #chatPanel,body[data-guided=true][data-step="4"] #chatPanel { display:none; }
body[data-guided=true][data-step="2"] main { display:none; }
body[data-guided=true][data-step="1"] main>article,body[data-guided=true][data-step="1"] .inspector,body[data-guided=true][data-step="1"] .shot-board,body[data-guided=true][data-step="1"] .snapshot-section { display:none; }
body[data-guided=true][data-step="3"] .audio-section,body[data-guided=true][data-step="3"] .snapshot-section,body[data-guided=true][data-step="3"] .timeline,body[data-guided=true][data-step="3"] .render-section { display:none; }
body[data-guided=true][data-step="4"] main>aside:not(.inspector),body[data-guided=true][data-step="4"] .inspector>section:not(.render-section),body[data-guided=true][data-step="4"] .preview,body[data-guided=true][data-step="4"] #takes,body[data-guided=true][data-step="4"] #compareButton { display:none; }
body[data-guided=true] .inspector { display:block; border:0; }
#flowSummary { overflow-wrap:anywhere; }
#flowNext { margin-left:var(--ui-space-6); }
.timeline { overflow-x:auto; }
.clip-row { min-width:430px; }
.row { flex-wrap:wrap; }
input,textarea,select { max-width:100%; }
dialog .row>button { flex:0 0 auto; }
#notice { overflow-wrap:anywhere; }
.skip-link { position:fixed; top:-60px; left:8px; z-index:10; padding:10px; background:white; color:black; }
.skip-link:focus { top:8px; }
@media(max-width:700px) {
.toolbar { gap:var(--ui-space-2); }
.toolbar>button { font-size:var(--ui-body-size); }
.flow-nav,.flow-summary { padding:var(--ui-space-3); }
button { min-height:44px; }
.caption-row { grid-template-columns:1fr 1fr; }
.caption-row input[data-field=text] { grid-column:1/-1; }
.row>label { flex-basis:160px; }
#chatPanel { padding:var(--ui-space-3)!important; }
.toolbar select { width:100%; }
}
.lt-ui .creator-source>summary { display:flex; align-items:center; gap:7px; list-style:none; cursor:pointer; }
.lt-ui .creator-source>summary::-webkit-details-marker { display:none; }
.lt-ui .creator-source>summary::before { content:'›'; display:inline-block; font-size:var(--ui-context); line-height:1; transform:rotate(0deg); }
.lt-ui .creator-source[open]>summary::before { transform:rotate(90deg); }
.lt-ui .creator-source>summary:focus-visible { border-radius:2px; }
#modelSettingsPanel { padding-inline:var(--ui-space-4); }
#modelSettingsPanel p { line-height:1.6; overflow-wrap:anywhere; }
#modelDefaultsBar { padding-block:6px; font-size:var(--ui-meta); }
#modelDefaultsSummary { flex:1; min-width:0; overflow-wrap:anywhere; }
header { gap:20px; }
.toolbar { padding-block:10px; }
.flow-nav { padding-block:10px; }
.flow-summary { padding-bottom:var(--ui-space-4); }
#flowHeading { font-size:var(--ui-title); line-height:var(--ui-leading-heading); margin-bottom:var(--ui-space-2); }
#flowSummary { color:var(--ui-muted); max-width:90ch; line-height:1.65; }
#flowNext { margin:var(--ui-space-2) 0 0; background:var(--ui-strong); color:var(--ui-canvas); border-color:var(--ui-strong); font-weight:var(--ui-weight-heading); }
#flowNext:hover { background:var(--ui-body); }
button, .download, input, select, textarea { border-radius:var(--ui-radius-control); }
button[aria-pressed=true] { box-shadow:inset 0 -3px 0 var(--ui-strong); }
summary { min-height:44px; padding-block:10px; }
.management summary { padding-inline:var(--ui-space-2); }
textarea { line-height:1.65; resize:vertical; }
.guided-card, .job { padding:20px; }
.guided-card h2, .job b { line-height:1.5; }
.guided-card li { margin-block:var(--ui-space-2); }
.badge { flex:0 1 auto; overflow-wrap:anywhere; }
.row, .flow-nav, .toolbar { min-width:0; }
.row > *, .toolbar > *, .flow-nav > * { max-width:100%; }
.preview { background:var(--ui-media); }
.take-strip { scroll-padding-inline:var(--ui-space-2); }
.take-strip button { flex:0 0 auto; }
@media(min-width:1000px) {
body[data-guided=true][data-step="3"] main { display:grid; grid-template-columns:220px minmax(0,1fr); align-items:start; }
body[data-guided=true][data-step="3"] main>.inspector { grid-column:1/-1; border-top:1px solid var(--ui-line); }
}
@media(max-width:700px) {
header { gap:var(--ui-space-3); }
#flowHeading { font-size:var(--ui-context); }
.flow-nav { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
.flow-nav button { padding-inline:var(--ui-space-2); }
.toolbar { padding-block:var(--ui-space-2); }
.guided-card, .job { padding:14px; }
#flowNext { width:100%; }
}
@media(prefers-reduced-motion:reduce) {
*, *::before, *::after { animation:none!important; transition:none!important; scroll-behavior:auto!important; }
}
.lt-ui { font:var(--ui-body-size)/1.5 var(--ui-font); }
.lt-ui :where(button,input,select,textarea,.download) { font:inherit; border-radius:var(--ui-radius-control); }
.lt-ui :where(button,.download) { min-height:40px; padding:var(--ui-space-2) var(--ui-space-3); border:1px solid var(--ui-control); background:var(--ui-raised); color:var(--ui-strong); }
.lt-ui :where(button,.download):not(:disabled):hover { background:var(--ui-hover); }
.lt-ui :where(button.primary,#flowNext) { background:var(--ui-primary); color:var(--ui-on-primary); border-color:var(--ui-primary); font-weight:var(--ui-weight-heading); }
.lt-ui :where(button.primary,#flowNext):not(:disabled):hover { background:var(--ui-body); }
.lt-ui button:disabled { opacity:1; background:var(--ui-raised); color:var(--ui-disabled); border-color:var(--ui-line); cursor:not-allowed; box-shadow:none; }
.lt-ui [aria-busy="true"] { cursor:progress; }
.lt-ui :where(button.active,button[aria-pressed="true"],.flow-nav button[aria-current="step"]) { color:var(--ui-strong); background:var(--ui-selected); border-color:var(--ui-control); box-shadow:inset 0 -2px var(--ui-strong); }
.lt-ui :focus-visible { outline:2px solid var(--ui-focus); outline-offset:3px; }
.lt-ui :where(input,select,textarea) { border:1px solid var(--ui-control); color:var(--ui-strong); min-width:0; }
.lt-ui :where(input,textarea)[aria-invalid="true"] { border-color:var(--ui-error); }
.lt-ui textarea { line-height:1.6; }
.lt-ui :where(p,li) { line-height:1.6; overflow-wrap:anywhere; }
.lt-ui :where(h1,#flowHeading) { font-size:var(--ui-title); line-height:var(--ui-leading-heading); font-weight:var(--ui-weight-heading); }
.lt-ui h2 { font-size:var(--ui-section); line-height:1.5; font-weight:var(--ui-weight-heading); }
.lt-ui h3 { font-size:var(--ui-body-size); line-height:1.5; font-weight:var(--ui-weight-heading); }
.lt-ui :where(small,.badge,#modelDefaultsBar) { font-size:var(--ui-meta); line-height:1.5; }
.lt-ui label { font-size:var(--ui-body-size); color:var(--ui-muted); }
.lt-ui header { min-height:48px; height:auto; padding:var(--ui-space-2) var(--ui-space-6); gap:var(--ui-space-4); }
.lt-ui header b { font-size:var(--ui-display); }
.lt-ui .lt-project-bar { display:flex; flex-wrap:wrap; align-items:center; border-bottom:1px solid var(--ui-line); }
.lt-ui .lt-project-bar>.toolbar { border-bottom:0; padding:6px var(--ui-space-6); }
.lt-ui .lt-project-bar>.toolbar:first-child { flex:1 1 540px; }
.lt-ui .lt-project-bar>.toolbar:last-child { flex:0 1 auto; }
.lt-ui .flow-summary { padding:var(--ui-space-1) var(--ui-space-6) var(--ui-space-3); display:grid; grid-template-columns:minmax(0,1fr) auto; gap:var(--ui-space-1) var(--ui-space-6); align-items:center; }
.lt-ui #flowSummary { margin:0; grid-column:1; max-width:90ch; }
.lt-ui #flowNext { grid-column:2; grid-row:1/3; }
.lt-ui #modelDefaultsBar { padding:6px var(--ui-space-6); }
.lt-ui #modelDefaultsSummary { color:var(--ui-muted); }
.lt-ui .preview { width:100%; max-width:720px; margin-inline:auto; background:var(--ui-media); border:1px solid var(--ui-line); border-radius:var(--ui-radius-control); }
.lt-ui .preview.portrait { max-width:300px; }
.lt-ui .preview :where(img,video) { object-fit:contain; }
.lt-ui .shot .thumb { flex-shrink:0; }
.lt-ui :where(.guided-card,.job,.timeline) { border:1px solid var(--ui-line); border-radius:var(--ui-radius-panel); background:var(--ui-panel); padding:var(--ui-space-4); }
.lt-ui .guided-card h2 { margin-bottom:var(--ui-space-3); }
.lt-ui .guided-card li { margin-block:var(--ui-space-2); }
.lt-ui .badge { border-radius:var(--ui-radius-clip); }
.lt-ui dialog { width:min(640px,calc(100vw - 32px)); max-height:calc(100dvh - 32px); border:1px solid var(--ui-control); }
.lt-ui dialog::backdrop { background:var(--ui-backdrop); }
