}

/* Bounded editing shell. Overflow stays reachable inside named panels; zoom/small
   windows use ordinary document flow. Playback controllers are unchanged. */
.lt-preview-stage { min-width:0; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) { height:100dvh; display:flex; flex-direction:column; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"])>.lt-studio-shell { flex:none; max-height:35dvh; overflow:auto; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"])>.lt-stage-bar { flex:none; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"])>.lt-edit-workspace { flex:1; min-height:0; width:100%; margin:0; align-items:stretch; overflow:auto; padding-bottom:var(--ui-space-4); }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) .lt-edit-workspace>:is(.lt-scene-rail,.inspector) { min-height:0; overflow:auto; overscroll-behavior:contain; scroll-padding-block:var(--ui-space-2); }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) .lt-media-pane { min-height:0; display:grid; grid-template-rows:minmax(0,1fr) auto; gap:var(--ui-space-2); overflow:auto; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) .lt-media-pane:has(.lt-timeline-controls[open]) { grid-template-rows:minmax(0,1fr) minmax(340px,38%); }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) .lt-preview-stage { min-height:0; display:flex; flex-direction:column; overflow:auto; scroll-padding-block:var(--ui-space-2); }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) .lt-preview-stage>* { flex:none; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) #preview { flex:1 1 auto; min-height:120px; height:auto; max-height:none; }
.lt-ui[data-desktop-shell=bounded] #sequenceTransport[data-mode=sequence] { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:var(--ui-space-1) var(--ui-space-3); }
.lt-ui[data-desktop-shell=bounded] #sequenceTransport .sequence-controls { margin:0; }
.lt-ui[data-desktop-shell=bounded] #sequenceTransport :is(#sequenceSeek,#sequenceStatus,#sequenceCaption) { grid-column:1/-1; }
.lt-ui[data-desktop-shell=bounded]:is([data-step="3"],[data-step="4"]) #ltTimelineDock { margin-top:0; min-height:0; display:flex; flex-direction:column; overflow:auto; }
